  tools.exec_command({cmd:"$ips='192.168.1.201','192.168.1.202','192.168.1.203','192.168.1.204'; Get-NetIPConfiguration | Where-Object {$_.IPv4Address} | Select-Object InterfaceAlias,@{N='IPv4';E={$_.IPv4Address.IPAddress}},@{N='Gateway';E={$_.IPv4DefaultGateway.NextHop}} | Format-Table -AutoSize; $rows=@(foreach($ip in $ips){[pscustomobject]@{Robot=$ip;Reachable=(Test-Connection -TargetName $ip -Count 2 -Quiet -ErrorAction SilentlyContinue)}}); $rows | Format-Table -AutoSize","workdir":"C:\\Users\\30973\\Documents\\Codex\\2026-09-17\\jix","max_output_tokens":1500}),
  tools.exec_command({cmd:"Get-Process | Where-Object { $_.ProcessName -match 'python|ssh|scp|ros|docker' } | Select-Object Id,ProcessName,Path,StartTime | Format-Table -AutoSize","workdir":"C:\\Users\\30973\\Documents\\Codex\\2026-09-17\\jix","max_output_tokens":1500}),
  tools.exec_command({cmd:"$p='C:\\Users\\30973\\Downloads\\四车编队交付.md'; Get-Content -LiteralPath $p -Tail 65 -Encoding UTF8","workdir":"C:\\Users\\30973\\Documents\\Codex\\2026-09-17\\jix","max_output_tokens":3000})
