"""Compare installed formation code and safety locks across all four robots."""

import json
import re
from pathlib import Path

import paramiko


document = Path(r"C:\Users\30973\Downloads\四车编队交付.md").read_text(encoding="utf-8")
match = re.search(r"我把密码直接发给你\s+([^\s<]+)", document)
if not match:
    raise RuntimeError("Previous SSH credential was not found in the handoff")

results = {}
for i in range(1, 5):
    host = f"192.168.1.{200 + i}"
    client = paramiko.SSHClient()
    client.load_host_keys(str(Path.home() / ".ssh" / "known_hosts"))
    client.set_missing_host_key_policy(paramiko.RejectPolicy())
    try:
        client.connect(host, username="pi", password=match.group(1), timeout=8,
                       auth_timeout=8, allow_agent=False, look_for_keys=False)
        commands = {
            "hashes": "docker exec MentorPi sha256sum /opt/openvela-formation/formation_lab/mentorpi_agent.py /opt/openvela-formation/formation_lab/formation_once.py /opt/openvela-formation/formation_lab/agent.py 2>&1",
            "agent": f"systemctl is-active formation-agent@robot{i}.service 2>&1",
            "locked": "docker exec MentorPi sh -lc 'python3 -c \"import json; print(json.load(open(\"\"/opt/openvela-formation/config/mentorpi.json\"\"))[\"\"hardware_output_enabled\"\"])\"; test ! -e /run/openvela-formation/command-arm.json && echo DISARMED || echo ARMED' 2>&1",
        }
        data = {}
        for key, command in commands.items():
            stdin, stdout, stderr = client.exec_command(command, timeout=12)
            data[key] = {"out": stdout.read().decode("utf-8", "replace").strip(),
                         "err": stderr.read().decode("utf-8", "replace").strip(),
                         "exit": stdout.channel.recv_exit_status()}
        results[f"robot{i}"] = data
    except Exception as exc:
        results[f"robot{i}"] = {"error": f"{type(exc).__name__}: {exc}"}
    finally:
        client.close()

print(json.dumps(results, ensure_ascii=False, indent=2))

